1	package reconcore
2	
3	import (
4		"encoding/json"
5		"errors"
6		"io"
7		"net/http"
8		"sort"
9		"strconv"
10		"strings"
11	)
12	
13	const maxBodyBytes = 1 << 20
14	
15	// Server adapts a Service onto net/http. It owns routing, request decoding and
16	// the documented error shape; every rule lives in the service layer.
17	type Server struct {
18		service *Service
19	}
20	
21	// NewServer builds the HTTP handler for one service.
22	func NewServer(service *Service) *Server {
23		return &Server{service: service}
24	}
25	
26	func (s *Server) ServeHTTP(writer http.ResponseWriter, request *http.Request) {
27		status, response, err := s.dispatch(request, splitPath(request.URL.Path))
28		if err != nil {
29			writeError(writer, err)
30			return
31		}
32		writeJSON(writer, status, response)
33	}
34	
35	func (s *Server) dispatch(request *http.Request, parts []string) (int, any, error) {
36		method := request.Method
37		switch {
38		case method == http.MethodGet && len(parts) == 1 && parts[0] == "health":
39			if err := requireQuery(request); err != nil {
40				return 0, nil, err
41			}
42			return http.StatusOK, map[string]any{"status": "ok"}, nil
43	
44		case method == http.MethodPost && len(parts) == 1 && parts[0] == "accounts":
45			body, err := readJSONBody(request)
46			if err != nil {
47				return 0, nil, err
48			}
49			response, err := s.service.CreateAccount(body, request.Header.Get("Idempotency-Key"))
50			return http.StatusCreated, response, err
51	
52		case method == http.MethodGet && len(parts) == 1 && parts[0] == "accounts":
53			if err := requireQuery(request); err != nil {
54				return 0, nil, err
55			}
56			response, err := s.service.ListAccounts()
57			return http.StatusOK, response, err
58	
59		case method == http.MethodGet && len(parts) == 2 && parts[0] == "accounts":
60			if err := requireQuery(request); err != nil {
61				return 0, nil, err
62			}
63			response, err := s.service.GetAccount(parts[1])
64			return http.StatusOK, response, err
65	
66		case method == http.MethodGet && len(parts) == 3 && parts[0] == "accounts" && parts[2] == "balance":
67			if err := requireQuery(request, "as_of"); err != nil {
68				return 0, nil, err
69			}
70			response, err := s.service.GetBalance(parts[1], request.URL.Query().Get("as_of"))
71			return http.StatusOK, response, err
72	
73		case method == http.MethodGet && len(parts) == 2 && parts[0] == "reports" && parts[1] == "trial-balance":
74			if err := requireSingleQuery(request, "as_of"); err != nil {
75				return 0, nil, err
76			}
77			response, err := s.service.GetTrialBalance(request.URL.Query().Get("as_of"))
78			return http.StatusOK, response, err
79	
80		case method == http.MethodGet && len(parts) == 2 && parts[0] == "reports" && parts[1] == "financial-statements":
81			query := request.URL.Query()
82			if err := requireNamedQueries(request, "as_of", "period_start", "period_end"); err != nil {
83				return 0, nil, err
84			}
85			response, err := s.service.GetFinancialStatements(
86				query.Get("as_of"), query.Get("period_start"), query.Get("period_end"),
87			)
88			return http.StatusOK, response, err
89	
90		case method == http.MethodPost && len(parts) == 1 && parts[0] == "journals":
91			body, err := readJSONBody(request)
92			if err != nil {
93				return 0, nil, err
94			}
95			response, err := s.service.CreateJournal(body, request.Header.Get("Idempotency-Key"))
96			return http.StatusCreated, response, err
97	
98		case method == http.MethodGet && len(parts) == 2 && parts[0] == "journals":
99			if err := requireQuery(request); err != nil {
100				return 0, nil, err
101			}
102			response, err := s.service.GetJournal(parts[1])
103			return http.StatusOK, response, err
104	
105		case method == http.MethodPost && len(parts) == 1 && parts[0] == "rates":
106			body, err := readJSONBody(request)
107			if err != nil {
108				return 0, nil, err
109			}
110			response, err := s.service.CreateRate(body, request.Header.Get("Idempotency-Key"))
111			return http.StatusCreated, response, err
112	
113		case method == http.MethodGet && len(parts) == 1 && parts[0] == "rates":
114			if err := requireQuery(request); err != nil {
115				return 0, nil, err
116			}
117			response, err := s.service.ListRates()
118			return http.StatusOK, response, err
119	
120		case method == http.MethodPost && len(parts) == 1 && parts[0] == "statements":
121			body, err := readJSONBody(request)
122			if err != nil {
123				return 0, nil, err
124			}
125			response, err := s.service.CreateStatement(body, request.Header.Get("Idempotency-Key"))
126			return http.StatusCreated, response, err
127	
128		case method == http.MethodGet && len(parts) == 2 && parts[0] == "statements":
129			if err := requireQuery(request); err != nil {
130				return 0, nil, err
131			}
132			response, err := s.service.GetStatement(parts[1])
133			return http.StatusOK, response, err
134	
135		case method == http.MethodPost && len(parts) == 1 && parts[0] == "reconciliations":
136			body, err := readJSONBody(request)
137			if err != nil {
138				return 0, nil, err
139			}
140			response, err := s.service.CreateReconciliation(body, request.Header.Get("Idempotency-Key"))
141			return http.StatusCreated, response, err
142	
143		case method == http.MethodGet && len(parts) == 2 && parts[0] == "reconciliations":
144			if err := requireQuery(request); err != nil {
145				return 0, nil, err
146			}
147			response, err := s.service.GetReconciliation(parts[1])
148			return http.StatusOK, response, err
149	
150		case method == http.MethodPost && len(parts) == 1 && parts[0] == "period-closes":
151			body, err := readJSONBody(request)
152			if err != nil {
153				return 0, nil, err
154			}
155			response, err := s.service.CreatePeriodClose(body, request.Header.Get("Idempotency-Key"))
156			return http.StatusCreated, response, err
157	
158		case method == http.MethodGet && len(parts) == 2 && parts[0] == "period-closes":
159			if err := requireQuery(request); err != nil {
160				return 0, nil, err
161			}
162			response, err := s.service.GetPeriodClose(parts[1])
163			return http.StatusOK, response, err
164	
165		case method == http.MethodPost && len(parts) == 3 && parts[0] == "period-closes" && parts[2] == "adjustments":
166			body, err := readJSONBody(request)
167			if err != nil {
168				return 0, nil, err
169			}
170			response, err := s.service.CreateAdjustment(parts[1], body, request.Header.Get("Idempotency-Key"))
171			return http.StatusCreated, response, err
172		}
173		return 0, nil, NotFoundError("route was not found")
174	}
175	
176	func readJSONBody(request *http.Request) ([]byte, error) {
177		contentType := request.Header.Get("Content-Type")
