1	package reconcore
2	
3	import (
4		"fmt"
5		"sort"
6		"time"
7	)
8	
9	// Service implements the ReconCore contract on top of a Store. The functional
10	// currency is fixed for the lifetime of the process and is the unit every
11	// journal is balanced in.
12	type Service struct {
13		store              *Store
14		functionalCurrency string
15		clock              func() time.Time
16	}
17	
18	// NewService wires a store, a functional currency and an injectable clock.
19	func NewService(store *Store, functionalCurrency string, clock func() time.Time) (*Service, error) {
20		if store == nil {
21			return nil, InternalError("service requires a store")
22		}
23		code, err := validateCurrency(functionalCurrency, "functional currency", true)
24		if err != nil {
25			return nil, err
26		}
27		if clock == nil {
28			clock = time.Now
29		}
30		return &Service{store: store, functionalCurrency: code, clock: clock}, nil
31	}
32	
33	// FunctionalCurrency reports the reporting currency of this process.
34	func (s *Service) FunctionalCurrency() string { return s.functionalCurrency }
35	
36	func (s *Service) now() string {
37		return s.clock().UTC().Format("2006-01-02T15:04:05Z")
38	}
39	
40	// runIdempotent executes action at most once per key. The first response is
41	// stored and replayed for every later request that carries the same key.
42	func (s *Service) runIdempotent(key, operation string, action func(state *State) (any, error)) (any, error) {
43		if key == "" {
44			return nil, ValidationError("Idempotency-Key header is required")
45		}
46		if len(key) > 200 {
47			return nil, ValidationError("Idempotency-Key must be at most 200 characters")
48		}
49		var response any
50		err := s.store.Update(func(state *State) error {
51			if record, found := state.Idempotency[key]; found {
52				if record.Operation != operation {
53					return ConflictError("idempotency key was already used for another operation")
54				}
55				stored, err := decodeResponse(record.Response)
56				if err != nil {
57					return err
58				}
59				response = stored
60				return nil
61			}
62			value, err := action(state)
63			if err != nil {
64				return err
65			}
66			normalized, err := normalizeResponse(value)
67			if err != nil {
68				return err
69			}
70			encoded, err := encodeResponse(normalized)
71			if err != nil {
72				return err
73			}
74			state.Idempotency[key] = &IdempotencyRecord{
75				Key:       key,
76				Operation: operation,
77				Response:  encoded,
78				CreatedAt: s.now(),
79			}
80			response = normalized
81			return nil
82		})
83		if err != nil {
84			return nil, err
85		}
86		return response, nil
87	}
88	
89	type createAccountRequest struct {
90		ID       string  `json:"id"`
91		Name     string  `json:"name"`
92		Type     string  `json:"type"`
93		ParentID *string `json:"parent_id"`
94		Currency string  `json:"currency"`
95	}
96	
97	// CreateAccount adds one node to the chart of accounts.
98	func (s *Service) CreateAccount(body []byte, key string) (any, error) {
99		var request createAccountRequest
100		if err := decodeObject(body, &request); err != nil {
101			return nil, err
102		}
103		id, err := validateIdentifier(request.ID, "account id")
104		if err != nil {
105			return nil, err
106		}
107		name, err := validateText(request.Name, "name")
108		if err != nil {
109			return nil, err
110		}
111		if name == "" {
112			return nil, ValidationError("name is required")
113		}
114		normalBalance, known := normalBalanceByType[request.Type]
115		if !known {
116			return nil, ValidationError("type must be one of asset, liability, equity, revenue or expense")
117		}
118		currency, err := validateCurrency(request.Currency, "currency", true)
119		if err != nil {
120			return nil, err
121		}
122		var parentID *string
123		if request.ParentID != nil {
124			value, err := validateIdentifier(*request.ParentID, "parent_id")
125			if err != nil {
126				return nil, err
127			}
128			parentID = &value
129		}
130		return s.runIdempotent(key, "create-account:"+id, func(state *State) (any, error) {
131			if _, found := state.Accounts[id]; found {
132				return nil, ConflictError("account %s already exists", id)
133			}
134			if parentID != nil {
135				if _, found := state.Accounts[*parentID]; !found {
136					return nil, ValidationError("parent_id %s does not exist", *parentID)
137				}
138			}
139			account := &Account{
140				ID:            id,
141				Name:          name,
142				Type:          request.Type,
143				ParentID:      parentID,
144				Currency:      currency,
145				NormalBalance: normalBalance,
146				CreatedAt:     s.now(),
147			}
148			state.Accounts[id] = account
149			return account, nil
150		})
151	}
152	
153	// ListAccounts returns the whole chart of accounts as a forest.
154	func (s *Service) ListAccounts() (any, error) {
155		return s.store.View(func(state *State) (any, error) {
156			_, roots := accountTree(state)
157			return map[string]any{"accounts": roots}, nil
158		})
159	}
160	
161	// GetAccount returns one account with its subtree.
162	func (s *Service) GetAccount(id string) (any, error) {
163		return s.store.View(func(state *State) (any, error) {
164			nodes, _ := accountTree(state)
165			node, found := nodes[id]
166			if !found {
167				return nil, NotFoundError("account %s was not found", id)
168			}
169			return node, nil
170		})
171	}
172	
173	// GetBalance derives the account balance at asOf from the journals only.
174	func (s *Service) GetBalance(id, asOf string) (any, error) {
175		if id == "" {
176			return nil, ValidationError("account id is required")
177		}
178		if asOf == "" {
179			return nil, ValidationError("as_of query parameter is required")
180		}
181		date, err := validateDate(asOf, "as_of")
182		if err != nil {
183			return nil, err
184		}
185		return s.store.View(func(state *State) (any, error) {
186			account, found := state.Accounts[id]
187			if !found {
188				return nil, NotFoundError("account %s was not found", id)
189			}
190			return s.computeBalance(state, account, date), nil
191		})
192	}
193	
194	func (s *Service) computeBalance(state *State, account *Account, asOf string) *Balance {
195		balance := &Balance{
196			AccountID:          account.ID,
197			AccountName:        account.Name,
198			AccountType:        account.Type,
199			NormalBalance:      account.NormalBalance,
200			Currency:           account.Currency,
201			FunctionalCurrency: s.functionalCurrency,
202			AsOf:               asOf,
203		}
204		for _, journal := range sortedJournals(state) {
205			if journal.Date > asOf {
206				continue
207			}
208			for _, line := range journal.Lines {
209				if line.AccountID != account.ID {
210					continue
211				}
212				balance.PostingCount++
213				if line.Side == "debit" {
214					balance.DebitMinor += line.AmountMinor
215					balance.FunctionalDebitMinor += line.FunctionalAmountMinor
216				} else {
217					balance.CreditMinor += line.AmountMinor
218					balance.FunctionalCreditMinor += line.FunctionalAmountMinor
219				}
220				if balance.FirstPostingDate == "" || journal.Date < balance.FirstPostingDate {
221					balance.FirstPostingDate = journal.Date
222				}
223				if journal.Date > balance.LastPostingDate {
224					balance.LastPostingDate = journal.Date
225				}
226			}
227		}
228		balance.NetMinor = balance.DebitMinor - balance.CreditMinor
229		balance.FunctionalNetMinor = balance.FunctionalDebitMinor - balance.FunctionalCreditMinor
230		balance.BalanceMinor = balance.NetMinor
231		if account.NormalBalance == "credit" {
232			balance.BalanceMinor = -balance.NetMinor
233		}
234		return balance
235	}
236	
237	// GetTrialBalance derives a read-only trial balance at asOf from the stored
238	// accounts and immutable journals. It never writes state and is recomputed
239	// from the current ledgers on every call.
240	func (s *Service) GetTrialBalance(asOf string) (any, error) {
241		if asOf == "" {
242			return nil, ValidationError("as_of query parameter is required")
243		}
244		date, err := validateDate(asOf, "as_of")
245		if err != nil {
246			return nil, err
247		}
248		return s.store.View(func(state *State) (any, error) {
249			rows := make(map[string]*TrialBalanceRow, len(state.Accounts))
250			ordered := make([]*TrialBalanceRow, 0, len(state.Accounts))
251			for _, account := range sortedAccounts(state) {
252				row := &TrialBalanceRow{
253					AccountID:   account.ID,
254					AccountName: account.Name,
255					Currency:    account.Currency,
256				}
257				rows[account.ID] = row
258				ordered = append(ordered, row)
259			}
260			for _, journal := range sortedJournals(state) {
261				if journal.Date > date {
262					continue
263				}
264				for _, line := range journal.Lines {
265					row := rows[line.AccountID]
266					if row == nil {
267						return nil, InternalError("journal %s posts to unknown account %s", journal.ID, line.AccountID)
268					}
269					row.PostingCount++
270					if line.Side == "debit" {
271						row.DebitMinor += line.AmountMinor
272						row.FunctionalDebitMinor += line.FunctionalAmountMinor
273					} else {
274						row.CreditMinor += line.AmountMinor
275						row.FunctionalCreditMinor += line.FunctionalAmountMinor
276					}
277				}
278			}
279			report := &TrialBalance{
280				AsOf:               date,
281				FunctionalCurrency: s.functionalCurrency,
282				Accounts:           ordered,
283			}
284			for _, row := range ordered {
285				row.NetMinor = row.DebitMinor - row.CreditMinor
286				row.FunctionalNetMinor = row.FunctionalDebitMinor - row.FunctionalCreditMinor
287				report.PostingCount += row.PostingCount
288				if row.FunctionalNetMinor >= 0 {
289					report.FunctionalDebitTotalMinor += row.FunctionalNetMinor
290				} else {
291					report.FunctionalCreditTotalMinor += -row.FunctionalNetMinor
292				}
293			}
294			report.Status = "balanced"
295			if report.FunctionalDebitTotalMinor != report.FunctionalCreditTotalMinor {
296				report.Status = "unbalanced"
297			}
298			return report, nil
299		})
300	}
301	
302	// GetFinancialStatements derives a read-only balance sheet at asOf and an
303	// income statement over the closed period [periodStart, periodEnd]. It is
304	// recomputed from the stored functional amounts on the immutable journals on
305	// every call, never writes state, creates no vouchers and changes no close.
306	func (s *Service) GetFinancialStatements(asOf, periodStart, periodEnd string) (any, error) {
307		if asOf == "" {
308			return nil, ValidationError("as_of query parameter is required")
309		}
310		asOfDate, err := validateDate(asOf, "as_of")
311		if err != nil {
312			return nil, err
313		}
314		if periodStart == "" {
315			return nil, ValidationError("period_start query parameter is required")
316		}
317		startDate, err := validateDate(periodStart, "period_start")
318		if err != nil {
319			return nil, err
320		}
321		if periodEnd == "" {
322			return nil, ValidationError("period_end query parameter is required")
323		}
324		endDate, err := validateDate(periodEnd, "period_end")
325		if err != nil {
326			return nil, err
327		}
328		if startDate > endDate {
329			return nil, ValidationError("period_start must not be after period_end")
330		}
331		if endDate > asOfDate {
332			return nil, ValidationError("period_end must not be after as_of")
333		}
334		return s.store.View(func(state *State) (any, error) {
335			accounts := sortedAccounts(state)
336	
337			// Functional debit and credit totals per account for the balance
338			// sheet window (through asOf) and the income window (the period).
339			asOfDebit := make(map[string]int64, len(accounts))
340			asOfCredit := make(map[string]int64, len(accounts))
341			periodDebit := make(map[string]int64, len(accounts))
342			periodCredit := make(map[string]int64, len(accounts))
343			for _, account := range accounts {
344				asOfDebit[account.ID] = 0
345				asOfCredit[account.ID] = 0
346				periodDebit[account.ID] = 0
347				periodCredit[account.ID] = 0
348			}
349			for _, journal := range sortedJournals(state) {
350				if journal.Date > asOfDate {
351					continue
352				}
353				inPeriod := journal.Date >= startDate && journal.Date <= endDate
354				for _, line := range journal.Lines {
355					if _, known := asOfDebit[line.AccountID]; !known {
356						return nil, InternalError("journal %s posts to unknown account %s", journal.ID, line.AccountID)
357					}
358					if line.Side == "debit" {
359						asOfDebit[line.AccountID] += line.FunctionalAmountMinor
360						if inPeriod {
361							periodDebit[line.AccountID] += line.FunctionalAmountMinor
362						}
363					} else {
364						asOfCredit[line.AccountID] += line.FunctionalAmountMinor
365						if inPeriod {
366							periodCredit[line.AccountID] += line.FunctionalAmountMinor
367						}
368					}
369				}
370			}
371	
372			balanceSheet := &BalanceSheet{
373				Assets:      []*FinancialStatementAccount{},
374				Liabilities: []*FinancialStatementAccount{},
375				Equity:      []*FinancialStatementAccount{},
376			}
377			incomeStatement := &IncomeStatement{
378				Revenue:  []*FinancialStatementAccount{},
379				Expenses: []*FinancialStatementAccount{},
380			}
381			for _, account := range accounts {
382				row := &FinancialStatementAccount{
383					AccountID:   account.ID,
384					AccountName: account.Name,
385					ParentID:    account.ParentID,
386					Currency:    account.Currency,
387				}
388				debitNormal := account.NormalBalance == "debit"
389				balance := asOfDebit[account.ID] - asOfCredit[account.ID]
390				if !debitNormal {
391					balance = -balance
392				}
393				row.FunctionalBalanceMinor = balance
394				switch account.Type {
395				case "asset":
396					balanceSheet.Assets = append(balanceSheet.Assets, row)
397					balanceSheet.AssetsTotalMinor += balance
398				case "liability":
399					balanceSheet.Liabilities = append(balanceSheet.Liabilities, row)
400					balanceSheet.LiabilitiesTotalMinor += balance
401				case "equity":
402					balanceSheet.Equity = append(balanceSheet.Equity, row)
403					balanceSheet.EquityTotalMinor += balance
404				case "revenue":
405					incomeStatement.Revenue = append(incomeStatement.Revenue, periodRow(account, periodCredit, periodDebit))
406					incomeStatement.RevenueTotalMinor += periodCredit[account.ID] - periodDebit[account.ID]
407				case "expense":
408					incomeStatement.Expenses = append(incomeStatement.Expenses, periodRow(account, periodDebit, periodCredit))
409					incomeStatement.ExpensesTotalMinor += periodDebit[account.ID] - periodCredit[account.ID]
410				}
411			}
412			incomeStatement.NetIncomeMinor = incomeStatement.RevenueTotalMinor - incomeStatement.ExpensesTotalMinor
413	
414			// Equity through as_of includes the income earned through as_of, so
415			// the accounting equation balances even before the books are closed.
416			var revenueThroughAsOf, expensesThroughAsOf int64
417			for _, account := range accounts {
418				switch account.Type {
419				case "revenue":
420					revenueThroughAsOf += asOfCredit[account.ID] - asOfDebit[account.ID]
421				case "expense":
422					expensesThroughAsOf += asOfDebit[account.ID] - asOfCredit[account.ID]
423				}
424			}
425			balanceSheet.EquityTotalMinor += revenueThroughAsOf - expensesThroughAsOf
426			balanceSheet.BalanceCheckMinor = balanceSheet.AssetsTotalMinor -
427				balanceSheet.LiabilitiesTotalMinor - balanceSheet.EquityTotalMinor
428			balanceSheet.Status = "balanced"
429			if balanceSheet.BalanceCheckMinor != 0 {
430				balanceSheet.Status = "unbalanced"
431			}
432			return &FinancialStatements{
433				AsOf:               asOfDate,
434				PeriodStart:        startDate,
435				PeriodEnd:          endDate,
436				FunctionalCurrency: s.functionalCurrency,
437				BalanceSheet:       balanceSheet,
438				IncomeStatement:    incomeStatement,
439			}, nil
440		})
441	}
442	
443	// periodRow builds the income-statement row for one account from the functional
444	// totals of journals dated inside the report period; positive holds the side
445	// that increases the account type (debits for expenses, credits for revenue)
446	// and negative the opposite side.
447	func periodRow(account *Account, positive, negative map[string]int64) *FinancialStatementAccount {
448		return &FinancialStatementAccount{
449			AccountID:              account.ID,
450			AccountName:            account.Name,
451			ParentID:               account.ParentID,
452			Currency:               account.Currency,
453			FunctionalBalanceMinor: positive[account.ID] - negative[account.ID],
454		}
455	}
