464	// CreateRate stores one exchange rate snapshot.
465	func (s *Service) CreateRate(body []byte, key string) (any, error) {
466		var request createRateRequest
467		if err := decodeObject(body, &request); err != nil {
468			return nil, err
469		}
470		base, err := validateCurrency(request.Base, "base", true)
471		if err != nil {
472			return nil, err
473		}
474		quote, err := validateCurrency(request.Quote, "quote", true)
475		if err != nil {
476			return nil, err
477		}
478		if base == quote {
479			return nil, ValidationError("base and quote must be different currencies")
480		}
481		date, err := validateDate(request.Date, "date")
482		if err != nil {
483			return nil, err
484		}
485		numerator, denominator, err := parseRateFraction(request.Rate, "rate")
486		if err != nil {
487			return nil, err
488		}
489		return s.runIdempotent(key, fmt.Sprintf("create-rate:%s/%s/%s", base, quote, date), func(state *State) (any, error) {
490			for _, existing := range state.Rates {
491				if existing.Base == base && existing.Quote == quote && existing.Date == date {
492					return nil, ConflictError("a %s/%s rate for %s already exists", base, quote, date)
493				}
494			}
495			rate := &Rate{
496				Base:        base,
497				Quote:       quote,
498				Date:        date,
499				Rate:        request.Rate,
500				Numerator:   numerator,
501				Denominator: denominator,
502				CreatedAt:   s.now(),
503			}
504			state.Rates = append(state.Rates, rate)
505			return rate, nil
506		})
507	}
