642	// CreatePeriodClose freezes one calendar month. The period must be exactly one
643	// natural month and no other close may cover the same month.
644	func (s *Service) CreatePeriodClose(body []byte, key string) (any, error) {
645		var request createPeriodCloseRequest
646		if err := decodeObject(body, &request); err != nil {
647			return nil, err
648		}
649		if _, err := validateIdentifier(request.ID, "period close id"); err != nil {
650			return nil, ValidationError("invalid period close id")
651		}
652		id := request.ID
653		start, err := validatePeriodCloseDate(request.Period.Start)
654		if err != nil {
655			return nil, err
656		}
657		end, err := validatePeriodCloseDate(request.Period.End)
658		if err != nil {
659			return nil, err
660		}
661		if !isCalendarMonth(start, end) {
662			return nil, ValidationError("period is not one calendar month")
663		}
664		return s.runIdempotent(key, "create-period-close:"+id, func(state *State) (any, error) {
665			if _, found := state.PeriodCloses[id]; found {
666				return nil, ConflictError("period close exists")
667			}
668			for _, existing := range state.PeriodCloses {
669				if existing.Period.Start[:7] == start[:7] {
670					return nil, ConflictError("calendar month is closed")
671				}
672			}
673			close := &PeriodClose{
674				ID:                   id,
675				Period:               Period{Start: start, End: end},
676				Status:               "closed",
677				ClosedAt:             s.now(),
678				AdjustmentCount:      0,
679				AdjustmentJournalIDs: []string{},
680			}
681			state.PeriodCloses[id] = close
682			return close, nil
683		})
684	}
685	
686	// validatePeriodCloseDate applies the public YYYY-MM-DD rule under the period
687	// close message.
688	func validatePeriodCloseDate(value string) (string, error) {
689		if _, err := validateDate(value, "period date"); err != nil {
690			return "", ValidationError("invalid period date")
691		}
692		return value, nil
693	}
694	
695	// isCalendarMonth reports whether start and end together span exactly one
696	// natural month, first day to last day.
697	func isCalendarMonth(start, end string) bool {
698		first, err := time.Parse(dateLayout, start)
699		if err != nil || first.Day() != 1 {
700			return false
701		}
702		last, err := time.Parse(dateLayout, end)
703		if err != nil {
704			return false
705		}
706		return last.Equal(first.AddDate(0, 1, -1))
707	}
