720	// CreateAdjustment posts an adjustment journal into a closed period through
721	// its close. The voucher follows every ordinary journal rule and additionally
722	// requires a memo and a date inside the closed period.
723	func (s *Service) CreateAdjustment(closeID string, body []byte, key string) (any, error) {
724		var request createJournalRequest
725		if err := decodeObject(body, &request); err != nil {
726			return nil, err
727		}
728		id, date, memo, err := validateJournalHead(request.ID, request.Date, request.Memo, len(request.Lines))
729		if err != nil {
730			return nil, err
731		}
732		return s.runIdempotent(key, "create-adjustment:"+closeID+":"+id, func(state *State) (any, error) {
733			close, found := state.PeriodCloses[closeID]
734			if !found {
735				return nil, NotFoundError("period close not found")
736			}
737			if memo == "" {
738				return nil, ValidationError("adjustment memo required")
739			}
740			if date < close.Period.Start || date > close.Period.End {
741				return nil, ValidationError("adjustment date outside period")
742			}
743			if _, found := state.Journals[id]; found {
744				return nil, ConflictError("journal exists")
745			}
746			journal, err := s.buildJournal(state, &request, id, date, memo)
747			if err != nil {
748				return nil, err
749			}
750			state.Journals[id] = journal
751			close.AdjustmentJournalIDs = append(close.AdjustmentJournalIDs, id)
752			close.AdjustmentCount = len(close.AdjustmentJournalIDs)
753			return journal, nil
754		})
755	}
