891			return nil, err
892		}
893		accountID, err := validateIdentifier(request.AccountID, "account_id")
894		if err != nil {
895			return nil, err
896		}
897		currency, err := validateCurrency(request.Currency, "currency", false)
898		if err != nil {
899			return nil, err
900		}
901		start, err := validateDate(request.Period.Start, "period.start")
902		if err != nil {
903			return nil, err
904		}
905		end, err := validateDate(request.Period.End, "period.end")
906		if err != nil {
907			return nil, err
908		}
909		if start > end {
910			return nil, ValidationError("period.start must not be after period.end")
911		}
912		opening, err := validateAmount(request.OpeningBalanceMinor, "opening_balance_minor", true, true)
913		if err != nil {
914			return nil, err
915		}
916		closing, err := validateAmount(request.ClosingBalanceMinor, "closing_balance_minor", true, true)
917		if err != nil {
918			return nil, err
919		}
920		return s.runIdempotent(key, "create-statement:"+id, func(state *State) (any, error) {
921			if _, found := state.Statements[id]; found {
922				return nil, ConflictError("statement %s already exists", id)
923			}
924			account, found := state.Accounts[accountID]
925			if !found {
926				return nil, ValidationError("account_id %s does not exist", accountID)
927			}
928			if currency == "" {
929				currency = account.Currency
930			}
931			if currency != account.Currency {
932				return nil, ValidationError(
933					"currency %s must match the currency %s of account %s",
934					currency, account.Currency, accountID,
935				)
936			}
937			statement := &Statement{
938				ID:                  id,
939				AccountID:           accountID,
940				Currency:            currency,
941				Period:              Period{Start: start, End: end},
942				OpeningBalanceMinor: opening,
943				ClosingBalanceMinor: closing,
944				Lines:               []*StatementLine{},
945				CreatedAt:           s.now(),
946			}
947			total := opening
948			seen := map[string]bool{}
949			for position, raw := range request.Lines {
950				if raw == nil {
951					return nil, ValidationError("lines[%d] must be an object", position+1)
952				}
953				field := fmt.Sprintf("lines[%d]", position+1)
954				lineID, err := validateIdentifier(raw.ID, field+".id")
955				if err != nil {
956					return nil, err
957				}
958				if seen[lineID] {
959					return nil, ValidationError("statement line id %s is duplicated", lineID)
960				}
961				seen[lineID] = true
962				lineDate, err := validateDate(raw.Date, field+".date")
963				if err != nil {
964					return nil, err
965				}
966				if lineDate < start || lineDate > end {
967					return nil, ValidationError("%s.date must fall inside the statement period", field)
968				}
969				amount, err := validateAmount(raw.AmountMinor, field+".amount_minor", false, true)
970				if err != nil {
971					return nil, err
972				}
973				reference, err := validateText(raw.Reference, field+".reference")
974				if err != nil {
975					return nil, err
976				}
977				description, err := validateText(raw.Description, field+".description")
978				if err != nil {
979					return nil, err
980				}
981				total += amount
982				statement.Lines = append(statement.Lines, &StatementLine{
983					ID:          lineID,
984					Date:        lineDate,
985					AmountMinor: amount,
986					Reference:   reference,
987					Description: description,
988				})
989			}
990			if total != closing {
991				return nil, ValidationError(
992					"statement lines do not reconcile with the closing balance: opening %d plus lines %d is %d, not %d",
993					opening, total-opening, total, closing,
994				)
995			}
996			state.Statements[id] = statement
997			return statement, nil
998		})
999	}
1000	
1001	// GetStatement returns one imported statement.
1002	func (s *Service) GetStatement(id string) (any, error) {
1003		return s.store.View(func(state *State) (any, error) {
1004			statement, found := state.Statements[id]
1005			if !found {
1006				return nil, NotFoundError("statement %s was not found", id)
1007			}
1008			return statement, nil
1009		})
1010	}
1011	
1012	type createReconciliationRequest struct {
1013		ID          string `json:"id"`
1014		StatementID string `json:"statement_id"`
1015	}
1016	
1017	// CreateReconciliation matches one statement against the ledger activity of its
1018	// account and freezes the result.
1019	func (s *Service) CreateReconciliation(body []byte, key string) (any, error) {
1020		var request createReconciliationRequest
1021		if err := decodeObject(body, &request); err != nil {
1022			return nil, err
1023		}
1024		id, err := validateIdentifier(request.ID, "reconciliation id")
1025		if err != nil {
1026			return nil, err
1027		}
1028		statementID, err := validateIdentifier(request.StatementID, "statement_id")
1029		if err != nil {
1030			return nil, err
1031		}
1032		return s.runIdempotent(key, "create-reconciliation:"+id, func(state *State) (any, error) {
1033			if _, found := state.Reconciliations[id]; found {
1034				return nil, ConflictError("reconciliation %s already exists", id)
1035			}
1036			statement, found := state.Statements[statementID]
1037			if !found {
1038				return nil, NotFoundError("statement %s was not found", statementID)
1039			}
1040			reconciliation, err := s.computeReconciliation(state, statement, id, s.now())
1041			if err != nil {
1042				return nil, err
1043			}
1044			state.Reconciliations[id] = reconciliation
1045			return reconciliation, nil
1046		})
1047	}
1048	
1049	// GetReconciliation returns one stored reconciliation.
1050	func (s *Service) GetReconciliation(id string) (any, error) {
1051		return s.store.View(func(state *State) (any, error) {
1052			reconciliation, found := state.Reconciliations[id]
1053			if !found {
1054				return nil, NotFoundError("reconciliation %s was not found", id)
1055			}
1056			return reconciliation, nil
1057		})
1058	}
1059	
1060	// ledgerEntry is one journal line seen from the ledger side of a
1061	// reconciliation. AmountMinor is signed with debits positive.
1062	type ledgerEntry struct {
1063		ID          string
1064		Date        string
1065		AmountMinor int64
1066		Reference   string
1067	}
1068	
1069	func ledgerEntries(state *State, accountID string, period Period) []*ledgerEntry {
1070		entries := []*ledgerEntry{}
1071		for _, journal := range sortedJournals(state) {
1072			if journal.Date < period.Start || journal.Date > period.End {
1073				continue
1074			}
1075			for _, line := range journal.Lines {
1076				if line.AccountID != accountID {
1077					continue
1078				}
1079				amount := line.AmountMinor
1080				if line.Side == "credit" {
1081					amount = -amount
1082				}
1083				entries = append(entries, &ledgerEntry{
1084					ID:          fmt.Sprintf("%s#%d", journal.ID, line.Index),
1085					Date:        journal.Date,
1086					AmountMinor: amount,
1087					Reference:   line.Reference,
1088				})
1089			}
1090		}
1091		return entries
1092	}
1093	
1094	var differenceOrder = map[string]int{
1095		"timing":               0,
1096		"amount_mismatch":      1,
1097		"missing_in_ledger":    2,
1098		"missing_in_statement": 3,
1099	}
1100	
1101	// computeReconciliation matches statement lines to ledger lines in three
1102	// deterministic tiers and classifies everything that stays unmatched.
1103	func (s *Service) computeReconciliation(state *State, statement *Statement, id, createdAt string) (*Reconciliation, error) {
1104		lines := make([]*StatementLine, 0, len(statement.Lines))
1105		lines = append(lines, statement.Lines...)
1106		sort.Slice(lines, func(left, right int) bool { return lines[left].ID < lines[right].ID })
1107	
1108		entries := ledgerEntries(state, statement.AccountID, statement.Period)
1109		sort.Slice(entries, func(left, right int) bool { return entries[left].ID < entries[right].ID })
1110	
1111		statementUsed := make([]bool, len(lines))
1112		ledgerUsed := make([]bool, len(entries))
1113		differences := []*Difference{}
1114		matched := 0
1115		match := func(statementIndex, ledgerIndex int, difference *Difference) {
1116			statementUsed[statementIndex] = true
1117			ledgerUsed[ledgerIndex] = true
1118			matched++
1119			if difference != nil {
1120				differences = append(differences, difference)
1121			}
1122		}
1123	
1124		// Tier 1: same signed amount and same date.
1125		for index, line := range lines {
1126			for other, entry := range entries {
1127				if ledgerUsed[other] {
1128					continue
1129				}
1130				if entry.AmountMinor == line.AmountMinor && entry.Date == line.Date {
1131					match(index, other, nil)
1132					break
1133				}
1134			}
1135		}
1136	
1137		// Tier 2: same signed amount, different date, so it only differs in timing.
1138		for index, line := range lines {
1139			if statementUsed[index] {
1140				continue
1141			}
1142			for other, entry := range entries {
1143				if ledgerUsed[other] || entry.AmountMinor != line.AmountMinor {
1144					continue
1145				}
1146				statementAmount := line.AmountMinor
1147				ledgerAmount := entry.AmountMinor
1148				match(index, other, &Difference{
1149					Type:                 "timing",
1150					Detail:               "the amounts agree but the ledger date differs from the statement date",
1151					StatementLineID:      line.ID,
1152					LedgerLineID:         entry.ID,
1153					StatementDate:        line.Date,
1154					LedgerDate:           entry.Date,
1155					StatementAmountMinor: &statementAmount,
1156					LedgerAmountMinor:    &ledgerAmount,
1157				})
1158				break
1159			}
1160		}
1161	
1162		// Tier 3: same non-empty reference but a different amount.
1163		for index, line := range lines {
1164			if statementUsed[index] || line.Reference == "" {
1165				continue
1166			}
1167			for other, entry := range entries {
1168				if ledgerUsed[other] || entry.Reference == "" || entry.Reference != line.Reference {
1169					continue
1170				}
1171				statementAmount := line.AmountMinor
1172				ledgerAmount := entry.AmountMinor
1173				match(index, other, &Difference{
1174					Type:                 "amount_mismatch",
1175					Detail:               fmt.Sprintf("reference %s appears on both sides with different amounts", line.Reference),
1176					StatementLineID:      line.ID,
1177					LedgerLineID:         entry.ID,
1178					StatementDate:        line.Date,
1179					LedgerDate:           entry.Date,
1180					StatementAmountMinor: &statementAmount,
1181					LedgerAmountMinor:    &ledgerAmount,
1182					DifferenceMinor:      statementAmount - ledgerAmount,
1183				})
1184				break
1185			}
1186		}
1187	
1188		// Everything still unmatched is missing on one side.
1189		for index, line := range lines {
1190			if statementUsed[index] {
1191				continue
1192			}
1193			amount := line.AmountMinor
1194			differences = append(differences, &Difference{
1195				Type:                 "missing_in_ledger",
1196				Detail:               "the statement line has no journal line in the period",
1197				StatementLineID:      line.ID,
1198				StatementDate:        line.Date,
1199				StatementAmountMinor: &amount,
1200				DifferenceMinor:      amount,
1201			})
1202		}
1203		for index, entry := range entries {
1204			if ledgerUsed[index] {
1205				continue
1206			}
1207			amount := entry.AmountMinor
1208			differences = append(differences, &Difference{
1209				Type:              "missing_in_statement",
1210				Detail:            "the journal line has no statement line in the period",
1211				LedgerLineID:      entry.ID,
1212				LedgerDate:        entry.Date,
1213				LedgerAmountMinor: &amount,
1214				DifferenceMinor:   -amount,
1215			})
1216		}
1217	
1218		sort.SliceStable(differences, func(left, right int) bool {
1219			a, b := differences[left], differences[right]
1220			if differenceOrder[a.Type] != differenceOrder[b.Type] {
1221				return differenceOrder[a.Type] < differenceOrder[b.Type]
1222			}
1223			if a.StatementLineID != b.StatementLineID {
1224				return a.StatementLineID < b.StatementLineID
1225			}
1226			return a.LedgerLineID < b.LedgerLineID
1227		})
1228	
1229		var ledgerNet int64
1230		for _, entry := range entries {
1231			ledgerNet += entry.AmountMinor
1232		}
1233		statementNet := statement.ClosingBalanceMinor - statement.OpeningBalanceMinor
1234	
1235		summary := DifferenceSummary{}
1236		var explained int64
1237		for _, difference := range differences {
1238			explained += difference.DifferenceMinor
1239			switch difference.Type {
1240			case "timing":
1241				summary.Timing++
1242			case "amount_mismatch":
1243				summary.AmountMismatch++
1244			case "missing_in_ledger":
1245				summary.MissingInLedger++
1246			case "missing_in_statement":
1247				summary.MissingInStatement++
1248			default:
1249				return nil, InternalError("reconciliation produced the unknown difference type %s", difference.Type)
1250			}
1251		}
1252		if 2*matched+summary.MissingInLedger+summary.MissingInStatement != len(lines)+len(entries) {
1253			return nil, InternalError("reconciliation differences are not mutually exclusive and complete")
1254		}
1255		if explained != statementNet-ledgerNet {
1256			return nil, InternalError("reconciliation differences do not add up to the period difference")
1257		}
1258	
1259		status := "balanced"
1260		if len(differences) > 0 {
1261			status = "differences_found"
1262		}
1263		return &Reconciliation{
1264			ID:                 id,
1265			StatementID:        statement.ID,
1266			AccountID:          statement.AccountID,
1267			Currency:           statement.Currency,
1268			FunctionalCurrency: s.functionalCurrency,
1269			Period:             statement.Period,
1270			Status:             status,
1271			MatchedCount:       matched,
1272			StatementLineCount: len(lines),
1273			LedgerLineCount:    len(entries),
1274			StatementNetMinor:  statementNet,
1275			LedgerNetMinor:     ledgerNet,
1276			DifferenceMinor:    statementNet - ledgerNet,
1277			Summary:            summary,
1278			Differences:        differences,
1279			CreatedAt:          createdAt,
1280		}, nil
1281	}
1282	
1283	func sortedAccounts(state *State) []*Account {
1284		accounts := make([]*Account, 0, len(state.Accounts))
1285		for _, account := range state.Accounts {
1286			accounts = append(accounts, account)
1287		}
1288		sort.Slice(accounts, func(left, right int) bool { return accounts[left].ID < accounts[right].ID })
1289		return accounts
1290	}
1291	
1292	func sortedJournals(state *State) []*Journal {
1293		journals := make([]*Journal, 0, len(state.Journals))
1294		for _, journal := range state.Journals {
1295			journals = append(journals, journal)
1296		}
1297		sort.Slice(journals, func(left, right int) bool {
1298			if journals[left].Date != journals[right].Date {
1299				return journals[left].Date < journals[right].Date
1300			}
1301			return journals[left].ID < journals[right].ID
1302		})
1303		return journals
1304	}
1305	
1306	func sortedRates(state *State) []*Rate {
1307		rates := make([]*Rate, 0, len(state.Rates))
1308		rates = append(rates, state.Rates...)
1309		sort.Slice(rates, func(left, right int) bool {
1310			a, b := rates[left], rates[right]
1311			if a.Base != b.Base {
1312				return a.Base < b.Base
1313			}
1314			if a.Quote != b.Quote {
1315				return a.Quote < b.Quote
1316			}
1317			return a.Date < b.Date
1318		})
1319		return rates
1320	}
1321	
1322	func accountTree(state *State) (map[string]*AccountNode, []*AccountNode) {
1323		nodes := map[string]*AccountNode{}
1324		for _, account := range state.Accounts {
1325			nodes[account.ID] = &AccountNode{Account: *account, Children: []*AccountNode{}}
1326		}
1327		roots := []*AccountNode{}
1328		for _, account := range sortedAccounts(state) {
1329			node := nodes[account.ID]
1330			if account.ParentID == nil {
1331				roots = append(roots, node)
1332				continue
1333			}
1334			parent, found := nodes[*account.ParentID]
1335			if !found {
1336				roots = append(roots, node)
1337				continue
1338			}
1339			parent.Children = append(parent.Children, node)
1340		}
1341		return nodes, roots
1342	}
1343	
1344	// latestRate returns the most recent snapshot for one direction that is
1345	// effective on the given date.
1346	func latestRate(state *State, base, quote, asOf string) *Rate {
1347		var best *Rate
1348		for _, rate := range state.Rates {
1349			if rate.Base != base || rate.Quote != quote || rate.Date > asOf {
1350				continue
1351			}
1352			if best == nil || rate.Date > best.Date {
1353				best = rate
1354			}
1355		}
1356		return best
1357	}
