type createStatementRequest struct {
	ID                  string                  `json:"id"`
	AccountID           string                  `json:"account_id"`
	Currency            string                  `json:"currency"`
	Period              periodRequest           `json:"period"`
	OpeningBalanceMinor int64                   `json:"opening_balance_minor"`
